// ═══ Usage model ═════════════════════════════════════════════════════════════════════════════════

usage : UsageModel { }
// browser: Anonymous window shopper: the product list, then product pages, sometimes back to the
// list (search/browse). MiSArch serves public products without a token (catalog Query.products:
// anonymous users see public products), so no login.
// 56.5810 sessions/s (open, Poisson); 4.28 requests per session
usage.usageScenario -- session_browser
// cartAbandoner: Puts items into the cart and leaves (Gatling abortedBuyProcessScenario, with
// browsing first).
// 15.9134 sessions/s (open, Poisson); 7.63 requests per session
usage.usageScenario -- session_cartAbandoner
// buyer: Puts items into the cart and buys (Gatling buyProcessScenario, with browsing first).
// 7.9567 sessions/s (open, Poisson); 11.63 requests per session
usage.usageScenario -- session_buyer
// account: Returning customer: logs in and does one to three account tasks; the tasks' weights are
// round 2's assumed rates of these operations.
// 7.9567 sessions/s (open, Poisson); 3.80 requests per session
usage.usageScenario -- session_account
// admin: Employee maintaining the catalogue, stock, prices, discounts, taxes and shipment methods;
// weights are round 2's assumed admin rates. Its own scenario with a constant rate: admin work does
// not follow the customers' load (R2 scaled it with the load).
// 0.4453 sessions/s (open, Poisson); 3.10 requests per session
usage.usageScenario -- session_admin

// ── session_browser ──────────────────────────────────────────────────────────────────────────────

session_browser : UsageScenario {
    entityName = "session_browser"
}
session_browser.workload -- session_browser_workload
session_browser.scenarioBehaviour -- session_browser_behaviour

session_browser_workload : OpenWorkload {
    interArrivalTime = "Exp(56.58103221)"
}

session_browser_behaviour : ScenarioBehaviour {
    entityName = "session_browser_behaviour"
}
session_browser_behaviour.actions -- session_browser_start
session_browser_behaviour.actions -- session_browser_callProducts
session_browser_behaviour.actions -- session_browser_loop
session_browser_behaviour.actions -- session_browser_stop

session_browser_start : Start { }

session_browser_callProducts : EntryLevelSystemCall { }
session_browser_callProducts.providedRole -- MiSArch_provides_IGateway
session_browser_callProducts.operationSignature -- IGateway_products

session_browser_loop : Loop {
    loopIteration = "IntPMF[(1;0.35)(2;0.25)(3;0.15)(4;0.10)(5;0.08)(6;0.07)]"
}
session_browser_loop.bodyBehaviour -- session_browser_loop_body

session_browser_loop_body : ScenarioBehaviour {
    entityName = "session_browser_loopBody_1"
}
session_browser_loop_body.actions -- session_browser_loop_start
session_browser_loop_body.actions -- session_browser_loop_delay
session_browser_loop_body.actions -- session_browser_loop_callProduct
session_browser_loop_body.actions -- session_browser_loop_branch
session_browser_loop_body.actions -- session_browser_loop_stop

